"""audio_segmenter: Split audio/video files into chunks via ffmpeg silence detection.

Adapted from audio-transcribe ai-service. Shorter default segment durations
(30s/60s) suit local single-file CLI use. No server-specific imports.
"""
from __future__ import annotations

import os
import re
import subprocess
from dataclasses import dataclass
from pathlib import Path

from atcli.utils.logger import get_logger

logger = get_logger(__name__)

# MIME types that contain video streams requiring audio extraction
_VIDEO_MIME_TYPES = frozenset({
    "video/mp4", "video/webm", "video/quicktime",
    "video/x-msvideo", "video/mpeg", "video/3gpp",
})

# Extension-based fallback for video detection when MIME type unavailable
_VIDEO_EXTENSIONS = frozenset({".mp4", ".mov", ".mkv", ".avi", ".webm", ".mpeg", ".3gp", ".m4v"})


def extract_audio_if_video(source_path: str, tmp_dir: str, mime_type: str | None = None) -> str:
    """Extract audio-only stream from a video file using ffmpeg stream copy.

    For audio-only files returns source_path unchanged. For video files writes
    audio to a .m4a file in tmp_dir and returns that path. Near-instant: uses
    '-c copy', no re-encoding.

    Args:
        source_path: Path to the original input file.
        tmp_dir:     Temp directory to write extracted audio into.
        mime_type:   MIME type hint; falls back to extension-based detection.

    Returns:
        Path to an audio-only file.
    """
    ext = Path(source_path).suffix.lower()
    is_video = (
        (mime_type in _VIDEO_MIME_TYPES) if mime_type
        else (ext in _VIDEO_EXTENSIONS)
    )

    if not is_video:
        return source_path

    audio_path = os.path.join(tmp_dir, "audio_extracted.m4a")
    cmd = ["ffmpeg", "-y", "-i", source_path, "-vn", "-acodec", "copy", audio_path]
    result = subprocess.run(cmd, capture_output=True, text=True)
    if result.returncode != 0:
        logger.warning(
            "Audio extraction failed (rc=%d), using original: %s",
            result.returncode, result.stderr[-300:],
        )
        return source_path

    logger.info("Extracted audio: %s -> %s", source_path, audio_path)
    return audio_path


@dataclass
class AudioSegment:
    """Represents a single audio segment slice with its file path and time range."""

    path: str
    start: float   # seconds from beginning of original audio
    end: float     # seconds from beginning of original audio

    @property
    def start_ms(self) -> int:
        return int(self.start * 1000)

    @property
    def duration(self) -> float:
        return self.end - self.start


class AudioSegmenter:
    """Split audio into segments by detecting silence points via ffmpeg.

    Ensures each segment length is between min_segment_duration and
    max_segment_duration. Falls back to hard cut when no silence is found.
    """

    def __init__(
        self,
        min_segment_duration: float = 30.0,
        max_segment_duration: float = 60.0,
        silence_threshold_db: float = -40.0,
        silence_min_duration: float = 1.0,
    ) -> None:
        self.min_segment_duration = min_segment_duration
        self.max_segment_duration = max_segment_duration
        self.silence_threshold_db = silence_threshold_db
        self.silence_min_duration = silence_min_duration

    def segment(self, audio_path: str, output_dir: str) -> list[AudioSegment]:
        """Split audio_path into segments written to output_dir.

        Returns list of AudioSegment (path, start, end) in chronological order.
        """
        os.makedirs(output_dir, exist_ok=True)
        total_duration = self._get_duration(audio_path)
        silence_points = self._detect_silence(audio_path)
        split_points = self._compute_split_points(silence_points, total_duration)

        starts = [0.0] + split_points
        ends = split_points + [total_duration]

        stem = Path(audio_path).stem
        ext = Path(audio_path).suffix
        segments: list[AudioSegment] = []

        for i, (start, end) in enumerate(zip(starts, ends)):
            out_path = os.path.join(output_dir, f"{stem}_seg{i:03d}{ext}")
            self._extract_segment(audio_path, start, end - start, out_path)
            segments.append(AudioSegment(path=out_path, start=start, end=end))
            logger.info("[%03d] %.1fs -> %.1fs (%.1fs) -> %s", i, start, end, end - start, out_path)

        logger.info("Created %d segments from %.1fs audio.", len(segments), total_duration)
        return segments

    def _get_duration(self, audio_path: str) -> float:
        cmd = [
            "ffprobe", "-v", "error",
            "-show_entries", "format=duration",
            "-of", "default=noprint_wrappers=1:nokey=1",
            audio_path,
        ]
        result = subprocess.run(cmd, capture_output=True, text=True, check=True)
        return float(result.stdout.strip())

    def _detect_silence(self, audio_path: str) -> list[float]:
        af = f"silencedetect=noise={self.silence_threshold_db}dB:d={self.silence_min_duration}"
        cmd = ["ffmpeg", "-i", audio_path, "-af", af, "-f", "null", "-"]
        result = subprocess.run(cmd, capture_output=True, text=True)
        ends: list[float] = []
        for line in result.stderr.splitlines():
            m = re.search(r"silence_end:\s*([\d.]+)", line)
            if m:
                ends.append(float(m.group(1)))
        return sorted(ends)

    def _compute_split_points(self, silence_points: list[float], total_duration: float) -> list[float]:
        split_points: list[float] = []
        last_cut = 0.0
        silence_idx = 0
        n = len(silence_points)

        while True:
            target_min = last_cut + self.min_segment_duration
            target_max = last_cut + self.max_segment_duration

            if target_min >= total_duration:
                break

            while silence_idx < n and silence_points[silence_idx] < target_min:
                silence_idx += 1

            if silence_idx < n and silence_points[silence_idx] <= target_max:
                cut = silence_points[silence_idx]
                silence_idx += 1
            else:
                cut = min(target_max, total_duration)

            if cut >= total_duration:
                break

            split_points.append(cut)
            last_cut = cut

        return split_points

    def _extract_segment(self, audio_path: str, start: float, duration: float, output_path: str) -> None:
        cmd = [
            "ffmpeg", "-y",
            "-ss", str(start), "-i", audio_path,
            "-t", str(duration), "-c", "copy",
            output_path,
        ]
        subprocess.run(cmd, capture_output=True, check=True)
